"""Tests for notebooks/colab_runbook.ipynb (generated by scripts/colab/build_colab_notebook.py, ADR 0016).

The notebook is the runnable companion to `COLAB_RUNBOOK.md` section 6 (one GPU part of the clean
campaign on `daninhas_full_fixed` per Colab account). These tests don't execute it (no GPU/Drive here,
`.claude/rules/data-safety.md`); they check that the committed file is what the generator emits, its
structure, the gates that make "Run all" stop early, and that it never carries a personal path.
"""

from __future__ import annotations

import importlib.util
import json
import re
import sys
from pathlib import Path

from dalmax import campaign as C

REPO_ROOT = Path(__file__).resolve().parent.parent
NOTEBOOK_PATH = REPO_ROOT / "notebooks" / "colab_runbook.ipynb"

# The runbook steps that must appear, in this relative order, across the notebook's code cells.
EXPECTED_COMMAND_ORDER = [
    "drive.mount",
    "uv python install 3.12",
    "poetry env use",
    "poetry install",
    '"colab-setup"',
    '"dataset-check"',
    '"colab-check"',
    "make campaign-list-gpu-part",
    "make campaign-run-gpu-part",
    "make campaign-verify-gpu-part",
    "zip -qr",
    "make campaign-report",
]


def _builder():
    path = REPO_ROOT / "scripts/colab/build_colab_notebook.py"
    spec = importlib.util.spec_from_file_location("build_colab_notebook", path)
    module = importlib.util.module_from_spec(spec)
    sys.modules["build_colab_notebook"] = module
    spec.loader.exec_module(module)
    return module


def _load_notebook() -> dict:
    with NOTEBOOK_PATH.open(encoding="utf-8") as fh:
        return json.load(fh)


def _code_sources() -> list[str]:
    return ["".join(c["source"]) for c in _load_notebook()["cells"] if c["cell_type"] == "code"]


def test_committed_notebook_matches_the_generator() -> None:
    assert NOTEBOOK_PATH.read_text(encoding="utf-8") == _builder().render(), "rerun scripts/colab/build_colab_notebook.py"


def test_notebook_is_valid_nbformat4_without_outputs() -> None:
    nb = _load_notebook()
    assert nb["nbformat"] == 4 and len(nb["cells"]) >= 20
    for cell in nb["cells"]:
        assert re.fullmatch(r"[A-Za-z0-9_-]{1,64}", cell["id"])
        if cell["cell_type"] == "code":
            assert cell["outputs"] == [] and cell["execution_count"] is None
            assert "".join(cell["source"]).strip()


def test_parameters_cell_has_a_placeholder_drive_root_and_gates_gpu_part() -> None:
    params = _code_sources()[0]
    assert 'DRIVE_ROOT = "/content/drive/MyDrive/<FOLDER_THAT_HOLDS_DATA>"' in params
    assert 'GPU_PART = "part_1_gpu"' in params and '"part_2_gpu"' in params
    assert 'raise ValueError(f"GPU_PART must be one of' in params
    assert 'if "<" in DRIVE_ROOT' in params  # an unfilled placeholder fails fast
    assert "MANIFEST" not in params and "PART = " not in params.replace("GPU_PART = ", "")


def test_expected_counts_match_the_manifests() -> None:
    manifests = [C.load_manifest(REPO_ROOT / p) for p in _builder().MANIFESTS]
    params = _code_sources()[0]
    for gpu_part in C.GPU_PARTS:
        jobs = [j for seg in C.plan_jobs(manifests, C.parse_selection(gpu_part)) for j in seg.jobs]
        assert f'"{gpu_part}": ({len(jobs)}, {len({j.group.id for j in jobs})})' in params


def test_no_personal_path_and_no_old_dataset() -> None:
    text = NOTEBOOK_PATH.read_text(encoding="utf-8")
    assert "UFMS" not in text and "Pós-graduação" not in text and "/home/" not in text
    assert "daninhas_full/" not in text and "daninhas_full\"" not in text
    assert "campaign-archive-superseded" not in text and "paper1_rerun" not in text


def test_dataset_gates_raise() -> None:
    sources = _code_sources()
    drive_gate = next(s for s in sources if "zip_path = f\"{DRIVE_ROOT}/DATA/{DATASET}.zip\"" in s)
    assert "raise FileNotFoundError" in drive_gate
    local_gate = next(s for s in sources if '"dataset-check"' in s)
    assert "n_files != DATASET_FILES" in local_gate and "check=True" in local_gate
    assert any('["make", "colab-setup"]' in s and "check=True" in s for s in sources)


def test_checkout_gate_refuses_modified_tracked_files() -> None:
    clone = next(s for s in _code_sources() if "git" in s and "clone" in s)
    assert '"status", "--porcelain", "--untracked-files=no"' in clone and "raise RuntimeError" in clone


def test_cell_right_before_the_run_asserts_the_count_and_the_other_part_is_absent() -> None:
    sources = _code_sources()
    run_idx = next(i for i, s in enumerate(sources) if "make campaign-run-gpu-part" in s)
    gate = sources[run_idx - 1]
    assert '"campaign-list-gpu-part", f"GPU_PART={GPU_PART}"' in gate and "check=True" in gate
    assert "(EXPECTED_RUNS, EXPECTED_GROUPS)" in gate
    assert '"campaign-verify-gpu-part", f"GPU_PART={OTHER_GPU_PART}"' in gate and "raise RuntimeError" in gate


def test_zip_cell_refuses_unless_verify_ok_and_ships_part_specific_logs() -> None:
    sources = _code_sources()
    verify = sources.index("!make campaign-verify-gpu-part GPU_PART={GPU_PART}")
    zip_idx = next(i for i, s in enumerate(sources) if "ZIP_PARTIAL = False" in s)
    assert verify < zip_idx
    cell = sources[zip_idx]
    assert "if n_ok != EXPECTED_RUNS and not ZIP_PARTIAL:" in cell
    assert "{name}_{GPU_PART}.log" in cell and "-x '{root}/campaign.log'" in cell
    assert "shutil.disk_usage" in cell and "n_models !=" in cell
    assert "!" not in cell.replace("!=", "")  # every step is a raising subprocess call


def test_gpu_identity_check_runs_right_after_colab_check() -> None:
    sources = _code_sources()
    check_idx = next(i for i, s in enumerate(sources) if '"colab-check"' in s)
    gpu_idx = next(i for i, s in enumerate(sources) if "results/colab_check/" in s and "run_metadata.json" in s)
    run_idx = next(i for i, s in enumerate(sources) if "make campaign-run-gpu-part" in s)
    assert check_idx < gpu_idx < run_idx
    assert 'f"DATA/{DATASET}/"' in sources[gpu_idx]  # the check run used the canonical dataset


def test_every_make_target_in_notebook_exists() -> None:
    makefile = (REPO_ROOT / "Makefile").read_text(encoding="utf-8")
    targets = set(re.findall(r"^([A-Za-z0-9_-]+):", makefile, flags=re.M))
    for source in _code_sources():
        used = re.findall(r"!make ([A-Za-z0-9_-]+)", source) + re.findall(r'\["make", "([A-Za-z0-9_-]+)"', source)
        for target in used:
            assert target in targets, f"notebook uses missing make target {target!r}"


def test_key_commands_appear_in_expected_order() -> None:
    full_source = "\n".join(_code_sources())
    position = 0
    for command in EXPECTED_COMMAND_ORDER:
        idx = full_source.find(command, position)
        assert idx != -1, f"expected command {command!r} not found (in order) in notebook"
        position = idx + len(command)


def test_notebook_has_colab_gpu_metadata() -> None:
    nb = _load_notebook()
    assert nb["metadata"]["accelerator"] == "GPU"
    assert "gpuType" not in nb["metadata"]["colab"]  # hardware-agnostic
    assert nb["metadata"]["kernelspec"]["name"] == "python3"


def test_kernel_python_version_is_not_forced_to_3_12() -> None:
    sources = _code_sources()
    assert not any("sys.version_info" in s and "raise" in s for s in sources)
    assert any('startswith("3.12")' in s and "poetry" in s for s in sources)
